// Resolve a print spec to {d, vb}: accepts {d, vb} as is, or {svg: "<any path or name>"} whose
// basename (without extension) names an embedded artwork, e.g. "brand/tools/print-wordmark-klein.json".
export function resolvePrint(spec) {
  if (!spec) return null;
  if (typeof spec === "string") spec = { svg: spec };
  if (spec.d && spec.vb) return spec;
  const key = String(spec.svg || spec.name || "").split("/").pop().replace(/\.(json|svg)$/i, "");
  const art = BRAND_PRINTS[key] || null;
  return art ? { ...spec, d: art.d, vb: art.vb } : null;
}
